mapper.select:
select
    widm.*
from wms_inbound_detail_manufactured widm
join wms_inbound_manufactured wim on widm.inbound_manufactured_id = wim.id and wim.bool_delete_enum = 0 and wim.review_status = 2
where widm.bool_delete_enum = 0

    and widm.basic_class & #{basicClass} > 0


    and widm.project_id = #{projectId}


    
        and wim.create_time > #{createTime[0]}
    
    
        and wim.create_time < #{createTime[1]}
    


    
        and wim.review_pass_time >= #{reviewPassTime[0]}
    
    
        and wim.review_pass_time <= #{reviewPassTime[1]}
    


    and wim.supplier_id = #{supplierId}


    and wim.purchase_SN like CONCAT('%', #{purchaseSN},'%')


    and wim.serial_number like CONCAT('%', #{serialNumber},'%')


    and wim.shipment_number like CONCAT('%', #{shipmentNumber},'%')


    and wim.license_plate like CONCAT('%', #{licensePlate},'%')


    and wim.applicant_name like concat('%',#{personName},'%')


    and widm.specification like concat('%',#{specification},'%')


    and widm.brand like concat('%',#{brand},'%')

select IFNULL(sum(widm.quantity),0) as quantity from wms_inbound_detail_manufactured widm left join wms_inbound_manufactured wim on widm.inbound_manufactured_id = wim.id where widm.bool_delete_enum = 0
and wim.review_status in
#{status}
and wim.purchase_id = #{purchaseId}

select widm.* FROM wms_inbound_detail_manufactured widm LEFT JOIN wms_inbound_manufactured wim ON wim.id = widm.inbound_manufactured_id and wim.bool_delete_enum = 0 where widm.bool_delete_enum = 0
and wim.purchase_id = #{purchaseId}
and wim.review_status = #{reviewStatus}

select widm.id, widm.purchase_order_detail_id purchaseDetailId, spo.id purchaseId, "2" type, wim.review_pass_time createTime FROM wms_inbound_detail_manufactured widm LEFT JOIN wms_inbound_manufactured wim ON wim.id = widm.inbound_manufactured_id and wim.bool_delete_enum = 0 INNER JOIN scm_purchase_order spo ON wim.purchase_id = spo.id AND spo.bool_delete_enum = 0 AND spo.data_status = 2 where widm.bool_delete_enum = 0 and wim.review_status = 2
and widm.basic_class & #{query.basicClassBit} > 0
and widm.basic_class = #{query.basicClass}
and wim.applicant_name like CONCAT('%', #{query.createUser},'%')
and widm.manufactured_name like CONCAT('%', #{query.className},'%')
and wim.review_pass_time >= #{query.startTime}
and wim.review_pass_time <= #{query.endTime}
and widm.project_id = #{query.projectId}
and spo.serial_number like CONCAT('%', #{query.purchaseSerialNumber},'%')
and spo.supplier_id = #{query.supplierId}
and widm.specification like CONCAT('%', #{query.specification},'%')
and spo.branch_company_id = #{query.branchCompanyId}
